/**
 * Phase 1 Interface for Majlis Al-Games
 *
 * Phase 1: Room Setup and Player Assignment
 * - Host creates room and configures game settings
 * - Players join via unique room code
 * - Role assignment occurs (traitor allocation)
 * - Minimum 4 players required to start
 */

import { validatePlayerCount, getTraitorAllocationDescription, type PlayerRole } from '../game/roleAssignment'

/**
 * Phase 1 state interface for room setup.
 */
export interface Phase1State {
  /** Room code generated by host */
  roomCode: string
  /** List of players who have joined */
  players: string[]
  /** Whether the minimum player count is met */
  minPlayersMet: boolean
  /** Traitor allocation description for display */
  traitorDescription: string
  /** Default traitor count based on player count */
  traitorCount: number
  /** Whether host has overridden the default traitor count */
  hostOverride: boolean
  /** Custom traitor count if host overrode default */
  customTraitorCount?: number
  /** Game settings */
  settings: {
    /** Whether sound effects are enabled */
    soundEffects: boolean
    /** Question time limit in seconds */
    questionTimeLimit?: number
  }
}

/**
 * Initializes a new Phase 1 state.
 *
 * @param roomCode Unique room code
 * @param settings Initial game settings
 * @returns Phase 1 state with validation
 */
export function initPhase1State(
  roomCode: string,
  settings: Phase1State['settings'] = {}
): Phase1State {
  return {
    roomCode,
    players: [],
    minPlayersMet: false,
    traitorDescription: 'Waiting for players...',
    traitorCount: 1,
    hostOverride: false,
    customTraitorCount: undefined,
    settings: {
      soundEffects: true,
      questionTimeLimit: 30,
      ...settings,
    },
  }
}

/**
 * Adds a player to the Phase 1 room.
 *
 * @param state Current Phase 1 state
 * @param nickname Player's chosen nickname
 * @returns Updated Phase 1 state
 */
export function addPlayerToPhase1(
  state: Phase1State,
  nickname: string
): Phase1State {
  const updatedPlayers = [...state.players, nickname]
  const totalPlayers = updatedPlayers.length

  const validation = validatePlayerCount(totalPlayers)
  const minPlayersMet = validation.isValid
  const traitorCount = validation.traitorCount

  const updatedTraitorDescription = minPlayersMet
    ? getTraitorAllocationDescription(totalPlayers)
    : 'Waiting for at least 4 players to start'

  return {
    ...state,
    players: updatedPlayers,
    minPlayersMet,
    traitorDescription: updatedTraitorDescription,
    traitorCount,
  }
}

/**
 * Removes a player from the Phase 1 room.
 *
 * @param state Current Phase 1 state
 * @param nickname Player's nickname to remove
 * @returns Updated Phase 1 state
 */
export function removePlayerFromPhase1(
  state: Phase1State,
  nickname: string
): Phase1State {
  const updatedPlayers = state.players.filter(p => p !== nickname)
  const totalPlayers = updatedPlayers.length

  const validation = validatePlayerCount(totalPlayers)
  const minPlayersMet = validation.isValid
  const traitorCount = validation.traitorCount

  const updatedTraitorDescription = minPlayersMet
    ? getTraitorAllocationDescription(totalPlayers)
    : 'Waiting for at least 4 players to start'

  return {
    ...state,
    players: updatedPlayers,
    minPlayersMet,
    traitorDescription: updatedTraitorDescription,
    traitorCount,
  }
}

/**
 * Configures traitor count with host override.
 *
 * @param state Current Phase 1 state
 * @param customTraitorCount Host's desired traitor count
 * @param hostOverride Whether this is a host override
 * @returns Updated Phase 1 state
 */
export function configureTraitorCount(
  state: Phase1State,
  customTraitorCount: number,
  hostOverride: boolean
): Phase1State {
  const totalPlayers = state.players.length

  // Validate the custom traitor count
  if (customTraitorCount < 1) {
    throw new Error('Traitor count must be at least 1')
  }
  if (customTraitorCount > totalPlayers - 1) {
    throw new Error(
      `Traitor count (${customTraitorCount}) exceeds maximum. ` +
      `Maximum traitors = total players - 1 (${totalPlayers - 1}), ` +
      `as at least one player must be loyal.`
    )
  }

  return {
    ...state,
    hostOverride,
    customTraitorCount,
    traitorCount: customTraitorCount,
    traitorDescription: getTraitorAllocationDescription(totalPlayers),
  }
}

/**
 * Starts the game from Phase 1, advancing to the next phase.
 *
 * @param state Current Phase 1 state
 * @returns Phase 1 state with isStarted flag set, ready for next phase
 */
export function startGameFromPhase1(
  state: Phase1State
): Phase1State & { gameStarted: boolean } {
  const totalPlayers = state.players.length

  if (!state.minPlayersMet) {
    throw new Error(
      `Cannot start game: minimum 4 players required. Current players: ${totalPlayers}`
    )
  }

  return {
    ...state,
    // In a real implementation, this would transition to phase 'setup' or 'question'
    // For now, we mark that the game initialization is complete
    gameStarted: true,
  }
}

/**
 * Gets the traitor allocation description based on current player count.
 *
 * @param totalPlayers Number of players
 * @returns Description string
 */
export function getPhase1TraitorDescription(totalPlayers: number): string {
  return getTraitorAllocationDescription(totalPlayers)
}

export default {
  initPhase1State,
  addPlayerToPhase1,
  removePlayerFromPhase1,
  configureTraitorCount,
  startGameFromPhase1,
  getPhase1TraitorDescription,
  validatePlayerCount,
}